import json
import numpy as np
S={}
for m in ('development-01','development-08','development-06'):
    fn='/workspace/work/done_%s.json'%m
    rows=(json.load(open(fn)).get('result') or {}).get('items',[])
    S[m]={x['id']:x for x in rows}
ids=['w_if_01','w_if_03','w_dl_01','w_dl_11','c_qa_01','c_qa_03','c_im_01','r_hle_01','r_ax_01','r_syn_1']
print('%-10s %-22s %-22s %-22s'%('item','dev-01','dev-08','dev-06'))
for i in ids:
    cells=[]
    for m in ('development-01','development-08','development-06'):
        x=S[m].get(i)
        cells.append('%.2f %s/%s'%(x.get('score'),x.get('answer_status')[:4],(x.get('finish_reason') or '')[:9]) if x else '-')
    print('%-10s %-22s %-22s %-22s'%(i,*cells))
dom={'coding':['c_qa_01','c_qa_03','c_im_01'],'co-work':['w_if_01','w_if_03','w_dl_01','w_dl_11'],'reasoning':['r_hle_01','r_ax_01','r_syn_1']}
meas={d:{m:float(np.mean([S[m][i]['score'] for i in v])) for m in S} for d,v in dom.items()}
print(); print('measured domain scores (10-item probe, OLD budgets):')
for d,v in meas.items(): print(' ',d,{k[-2:]:round(x,3) for k,x in v.items()})
T=json.load(open('/workspace/whitebox.json'))['targets']; D=json.load(open('/workspace/whitebox.json'))['domains']
def pear(x,y):
    x,y=np.array(x,float),np.array(y,float)
    if x.std()<1e-12 or y.std()<1e-12: return float('nan')
    return float(np.corrcoef(x,y)[0,1])
tot=[]
for d,ts in D.items():
    rs=[]
    for t in ts:
        sc=T[t]['scores']; ks=[k for k in meas[d] if k in sc]
        if len(ks)<3: print('   skip',t,len(ks)); continue
        r=pear([meas[d][k] for k in ks],[sc[k] for k in ks]); rs.append(r)
        print('   %-24s n=%d r=%s'%(t,len(ks),('%.3f'%r) if r==r else 'nan(constant)'))
    m=np.nanmean(rs) if rs else float('nan'); tot.append(m)
    print('  %s avg r=%s'%(d,('%.3f'%m) if m==m else 'nan'))
print('MACRO =', np.nanmean(tot))
PY",
  "description": "Compute 3-model probe correlations"
}

