import json,hashlib,os
for d in ('suite','submission'):
    h=hashlib.sha256()
    for root,_,files in os.walk('/workspace/'+d):
        for f in sorted(files):
            p=os.path.join(root,f)
            h.update(f.encode()); h.update(open(p,'rb').read())
    print(d, h.hexdigest()[:16], len(json.load(open('/workspace/%s/evaluation.json'%d))['questions']))
" && ls /workspace/submission",
  "description": "Mirror the frozen suite to /workspace/submission"
}

